-- Optional translation fields for future editorial writes.
alter table public.articles add column excerpt_en text, add column body_en text;

-- Separate, additive editions for existing posts. No source rows are rewritten.
create table public.article_editions (
  article_id uuid primary key references public.articles(id) on delete cascade,
  source_digest text not null,
  excerpt_bn text,
  excerpt_en text not null,
  body_en text not null
);
alter table public.article_editions enable row level security;
revoke all on public.article_editions from anon, authenticated;
grant select on public.article_editions to anon, authenticated;
create policy read_current_edition on public.article_editions for select using (
  exists (select 1 from public.articles a where a.id=article_id
    and a.status='published' and md5(a.body || chr(31) || a.excerpt || chr(31) || a.title_bn) = source_digest)
);

insert into public.article_editions(article_id,source_digest,excerpt_en,excerpt_bn,body_en)
select a.id,md5(a.body || chr(31) || a.excerpt || chr(31) || a.title_bn),a.excerpt,t.summary_bn,
  'Dhaka — ' || a.title || E'\n\n' || 'A special report from BD24News. The development has prompted widespread discussion across the country. Sources are examining it from several perspectives, and experts expect the situation to become clearer over the coming days.

BD24News spoke to several sources. According to the information they provided, the initiative will have a positive effect on people''s daily lives. The authorities concerned said all necessary preparations had been completed.

Experts say the decision will play an important role in the national economy over the long term. Implementation poses challenges, however. A roadmap has been drawn up to address them and will be put into effect in stages.

Public reactions have been mixed. Some people welcomed the initiative, while others expressed doubts about whether it would be implemented properly. The ministry concerned said the process would be transparent.

The development has also prompted discussion abroad. Media outlets in several countries are reporting on it. Bangladesh''s move is being viewed as an example for other South Asian countries.

The situation remained normal at the time of the latest reports. BD24News will update readers as new information becomes available. Our correspondents are working at the scene and gathering information firsthand.'
from public.articles a cross join (values
  ('ai-translate-bangla', '400a2ee817abde5878e3f55d4fbd5041', 'New open-source AI translation models trained on Bangla corpora are outperforming commercial engines in accuracy tests, offering free tools for millions of Bengali speakers worldwide.', 'বাংলা লেখা দিয়ে প্রশিক্ষিত নতুন উন্মুক্ত অনুবাদ মডেল নির্ভুলতার পরীক্ষায় বাণিজ্যিক ইঞ্জিনকে ছাড়িয়ে যাচ্ছে। বিশ্বজুড়ে লাখো বাংলাভাষী বিনা খরচে এগুলো ব্যবহার করতে পারবেন।'),
  ('air-pollution-dhaka', 'fa8e5963e1e79be025fec599ec6d6c61', 'Air quality in Dhaka worsened again this week, topping global pollution charts for the fifth consecutive day. Experts blame construction dust, brick kilns and vehicle emissions.', 'ঢাকায় এ সপ্তাহে বাতাসের মান আবারও খারাপ হয়েছে। টানা পঞ্চম দিনের মতো দূষণের বৈশ্বিক তালিকায় শীর্ষে শহরটি। বিশেষজ্ঞরা নির্মাণকাজের ধুলা, ইটভাটা ও যানবাহনের ধোঁয়াকে দায়ী করছেন।'),
  ('amphan-relief', '7d2a41ff74a550fbb29567c846173861', 'Reconstruction efforts are picking up pace in cyclone-hit coastal areas, with thousands of homes being rebuilt and livelihood support reaching affected families.', 'ঘূর্ণিঝড়ে ক্ষতিগ্রস্ত উপকূলে পুনর্গঠন ত্বরান্বিত হচ্ছে। হাজার হাজার ঘর পুনর্নির্মাণের পাশাপাশি ক্ষতিগ্রস্ত পরিবারগুলো জীবিকা নির্বাহের সহায়তা পাচ্ছে।'),
  ('bb-governor-new', '1e4dc5cf948c4bdb93bb3f1784c2a29f', 'The new governor of Bangladesh Bank has officially assumed office today, vowing to stabilise inflation, strengthen reserves and accelerate digital banking adoption across the country.', 'বাংলাদেশ ব্যাংকের নতুন গভর্নর আজ আনুষ্ঠানিকভাবে দায়িত্ব নিয়েছেন। মূল্যস্ফীতি নিয়ন্ত্রণ, রিজার্ভ শক্তিশালী করা এবং সারা দেশে ডিজিটাল ব্যাংকিংয়ের ব্যবহার বাড়ানোর অঙ্গীকার করেছেন তিনি।'),
  ('bd-chess-grandmaster', '943330e9db61b2a28a2c5678d493bfaf', 'At just 15, the country''s newest grandmaster sealed the title with a stunning win at an international tournament, inspiring a new generation of young chess players.', 'মাত্র ১৫ বছর বয়সে আন্তর্জাতিক প্রতিযোগিতায় দুর্দান্ত জয়ে গ্র্যান্ডমাস্টার খেতাব নিশ্চিত করেছে দেশের এই দাবাড়ু। তার সাফল্য নতুন প্রজন্মকে অনুপ্রাণিত করছে।'),
  ('bd-tourism-festival', 'b6376273a3b665042a245e3101c3329a', 'The three-day Bangladesh Tourism Festival drew record crowds at Suhrawardy Udyan, showcasing the country''s heritage, cuisine and natural beauty through 200 pavilions.', 'সোহরাওয়ার্দী উদ্যানে তিন দিনের বাংলাদেশ পর্যটন উৎসবে রেকর্ডসংখ্যক দর্শনার্থী এসেছেন। ২০০টি প্যাভিলিয়নে দেশের ঐতিহ্য, খাবার ও প্রাকৃতিক সৌন্দর্য তুলে ধরা হয়েছে।'),
  ('bengal-tiger-census', 'b66b1145d38954e35b254385fff6c9f3', 'A new camera-trap census reveals the Sundarbans tiger population has grown for the first time in a decade, a cautious win for conservation efforts.', 'ক্যামেরা ট্র্যাপের নতুন জরিপ বলছে, এক দশকে প্রথমবারের মতো সুন্দরবনে বাঘের সংখ্যা বেড়েছে। সংরক্ষণ উদ্যোগের জন্য এটি আশার খবর।'),
  ('border-trade', '4dbde05d2790a369c04c8c45aa240a4b', 'New border trade hubs are helping small and medium enterprises export directly to neighbouring markets, cutting costs and opening fresh opportunities.', 'নতুন সীমান্ত বাণিজ্যকেন্দ্র ক্ষুদ্র ও মাঝারি প্রতিষ্ঠানকে প্রতিবেশী দেশের বাজারে সরাসরি রপ্তানির সুযোগ দিচ্ছে। এতে খরচ কমছে এবং নতুন সুযোগ তৈরি হচ্ছে।'),
  ('budget-education', 'e57a09ca77a6f07672d7e0d8999848ed', 'The proposed national budget allocates significantly more funding to education, including scholarships, free textbooks and a major push to digitise primary schools.', 'প্রস্তাবিত জাতীয় বাজেটে শিক্ষায় বরাদ্দ উল্লেখযোগ্যভাবে বাড়ানো হয়েছে। এতে বৃত্তি, বিনা মূল্যের পাঠ্যবই ও প্রাথমিক বিদ্যালয় ডিজিটাল করার বড় উদ্যোগ রয়েছে।'),
  ('cinema-new-film', '329a591a119561db9f916cf4947d62cd', 'The critically acclaimed film Nodir Chhaya finally gets a wide release this week. Shot across the chars of northern Bangladesh, it has already won three international awards.', 'সমালোচকদের প্রশংসিত ‘নদীর ছায়া’ এ সপ্তাহে বড় পরিসরে মুক্তি পাচ্ছে। উত্তরবঙ্গের চরাঞ্চলে ধারণ করা ছবিটি ইতিমধ্যেই তিনটি আন্তর্জাতিক পুরস্কার জিতেছে।'),
  ('cl-final', 'a4246b29f6ef6e1d0749c13bb504fe81', 'Tonight''s Champions League final pits two European giants in a battle for continental glory. Our tactical breakdown predicts a cagey but explosive contest.', 'আজ রাতে চ্যাম্পিয়নস লিগের ফাইনালে মুখোমুখি ইউরোপের দুই পরাশক্তি। আমাদের কৌশলগত বিশ্লেষণ বলছে, দুই দল সতর্কভাবে খেললেও ম্যাচ হঠাৎ জমে উঠতে পারে।'),
  ('covid-update', '071f230357e834d56338733bca17181b', 'The health ministry has released updated guidelines for managing seasonal flu outbreaks, with a focus on protecting children and the elderly.', 'মৌসুমি ফ্লুর প্রাদুর্ভাব মোকাবিলায় স্বাস্থ্য মন্ত্রণালয় হালনাগাদ নির্দেশিকা প্রকাশ করেছে। শিশু ও প্রবীণদের সুরক্ষায় বিশেষ গুরুত্ব দেওয়া হয়েছে।'),
  ('cox-bazar-tourism', '7f97d9c6bf391dd7e63da27970101c87', 'With the tourist season officially beginning, Cox''s Bazar is rolling out upgraded facilities, cleanliness drives and new safety measures along the world''s longest natural beach.', 'পর্যটন মৌসুম শুরু হওয়ায় কক্সবাজারে বিশ্বের দীর্ঘতম প্রাকৃতিক সমুদ্রসৈকতে সুযোগ-সুবিধা উন্নয়ন, পরিচ্ছন্নতা অভিযান ও নতুন নিরাপত্তাব্যবস্থা চালু হচ্ছে।'),
  ('cricket-bpl-final', '3932611d4eb427e81737b090b1c1464b', 'Fortune Barishal lifted the BPL trophy after a last-ball thriller against Comilla Victorians. The captain''s unbeaten 88 earned a standing ovation from a packed Mirpur stadium.', 'শেষ বলের রোমাঞ্চে কুমিল্লা ভিক্টোরিয়ানসকে হারিয়ে বিপিএল ট্রফি জিতেছে ফরচুন বরিশাল। অধিনায়কের অপরাজিত ৮৮ রানে মিরপুরের গ্যালারিভর্তি দর্শক দাঁড়িয়ে অভিবাদন জানান।'),
  ('cyber-crime-bust', 'e646237e5c18512a11c482a05854b886', 'Rapid Action Battalion has dismantled a nationwide cyber fraud network, arresting six suspects accused of defrauding victims out of crores through fake investment schemes.', 'দেশজুড়ে সক্রিয় একটি অনলাইন প্রতারণা চক্র ভেঙে দিয়েছে র‌্যাব। ভুয়া বিনিয়োগ প্রকল্পের মাধ্যমে কোটি কোটি টাকা হাতিয়ে নেওয়ার অভিযোগে ছয় সন্দেহভাজনকে গ্রেপ্তার করা হয়েছে।'),
  ('cyclone-warning', '4f5f09c03328c25f4a1fc42065f62e8a', 'The Meteorological Department has issued a great danger signal for coastal districts as Cyclone Kabir intensifies in the Bay of Bengal. Thousands have been moved to cyclone shelters.', 'বঙ্গোপসাগরে ঘূর্ণিঝড় কবির শক্তি বাড়ানোয় উপকূলীয় জেলাগুলোতে মহাবিপদ সংকেত দিয়েছে আবহাওয়া অধিদপ্তর। হাজার হাজার মানুষকে আশ্রয়কেন্দ্রে সরানো হয়েছে।'),
  ('dengue-prevention', '5a9ba21b62e3c8bcc6b401930b5c47f9', 'Hospitals across Dhaka report a sharp rise in dengue admissions as the rainy season peaks. Health officials urge residents to destroy mosquito breeding grounds.', 'বর্ষার ভরা মৌসুমে ঢাকার হাসপাতালগুলোতে ডেঙ্গু রোগী ভর্তি দ্রুত বেড়েছে। স্বাস্থ্য কর্মকর্তারা মশার প্রজননস্থল ধ্বংস করার আহ্বান জানিয়েছেন।'),
  ('dhaka-art-biennale', '58cbc00e9d7256aa788af8b3932c660d', 'The Dhaka Art Summit returns with works by over 200 artists from across South Asia, blending traditional forms with bold contemporary experiments.', 'ঢাকা আর্ট সামিটে ফিরছে দক্ষিণ এশিয়ার দুই শতাধিক শিল্পীর কাজ। প্রদর্শনীতে ঐতিহ্যবাহী শিল্পরীতির সঙ্গে থাকছে সমকালীন শিল্পের সাহসী পরীক্ষা-নিরীক্ষা।'),
  ('education-digital', '7be488ed431a0df8d57346ca557482ba', 'The government''s flagship digital education programme has now reached 10,000 rural schools, giving millions of students access to interactive smart content for the first time.', 'সরকারের ডিজিটাল শিক্ষা কর্মসূচি এখন গ্রামের ১০ হাজার বিদ্যালয়ে পৌঁছেছে। প্রথমবারের মতো লাখো শিক্ষার্থী অংশগ্রহণমূলক ডিজিটাল পাঠ ব্যবহারের সুযোগ পাচ্ছে।'),
  ('eid-traffic', 'a639001f47496ac981eb96672f4d8352', 'Millions begin the annual Eid journey home as authorities launch special trains, buses and launch services. Ferries on major routes have been doubled.', 'ঈদে বাড়ি ফিরতে যাত্রা শুরু করেছেন লাখো মানুষ। বিশেষ ট্রেন, বাস ও লঞ্চ চালু করেছে কর্তৃপক্ষ। প্রধান নৌপথে ফেরির সংখ্যা দ্বিগুণ করা হয়েছে।'),
  ('film-festival-short', 'db089947c2ccf2a05f6feac135b8511d', 'A 15-minute short film from Dhaka has been selected for the official competition at Cannes, the first Bangladeshi film in a decade to earn the honour.', 'ঢাকার ১৫ মিনিটের একটি স্বল্পদৈর্ঘ্য চলচ্চিত্র কান উৎসবের আনুষ্ঠানিক প্রতিযোগিতায় নির্বাচিত হয়েছে। এক দশকে প্রথম বাংলাদেশি ছবি হিসেবে এই সম্মান পেল এটি।'),
  ('football-youth', 'fb9e56fadc235bdd235a642a7fc34cee', 'Bangladesh''s under-17 football team impressed at the Asian Championship, reaching the knockout stage for the first time in the country''s history.', 'এশিয়ান চ্যাম্পিয়নশিপে বাংলাদেশের অনূর্ধ্ব-১৭ ফুটবল দল দারুণ খেলেছে। দেশের ইতিহাসে প্রথমবারের মতো তারা নকআউট পর্বে পৌঁছেছে।'),
  ('gaza-ceasefire', '7d49311770fb64b06bada4d95762b294', 'A fragile ceasefire between Israel and Hamas took effect this morning. The first humanitarian aid convoy carrying food and medicine entered the enclave amid cautious hopes for lasting peace.', 'ইসরায়েল ও হামাসের মধ্যে নাজুক যুদ্ধবিরতি আজ সকালে কার্যকর হয়েছে। স্থায়ী শান্তির সতর্ক আশাবাদের মধ্যে খাদ্য ও ওষুধ নিয়ে প্রথম মানবিক সহায়তা বহর গাজায় প্রবেশ করেছে।'),
  ('gold-price-record', 'ead7b3e47fd4994521bf8dde7d45444c', 'Gold prices in Bangladesh touched another historic high today, rising Tk 1,150 per bhori amid a global rally in the yellow metal. Jewellers say demand remains steady ahead of the wedding season.', 'বিশ্ববাজারে মূল্যবৃদ্ধির মধ্যে দেশে সোনার দাম ভরিপ্রতি ১,১৫০ টাকা বেড়ে নতুন রেকর্ডে পৌঁছেছে। বিয়ের মৌসুমের আগে চাহিদা স্থিতিশীল বলে জানিয়েছেন জুয়েলারিরা।'),
  ('govt-digital-service', '26a843cbe10e8219d3af044b372909bf', 'The national digital services portal has relaunched with 500 services, letting citizens apply for documents, pay bills and track cases without visiting offices.', '৫০০টি সেবা নিয়ে জাতীয় ডিজিটাল সেবা পোর্টাল আবার চালু হয়েছে। নাগরিকরা অফিসে না গিয়েই নথির আবেদন, বিল পরিশোধ ও আবেদনের অগ্রগতি দেখতে পারবেন।'),
  ('green-energy', '829d0ff544a32da5d5e2609872d260bb', 'In a historic first, solar power contributed more to the national grid than coal last month, underscoring the country''s renewable energy transition.', 'গত মাসে প্রথমবারের মতো জাতীয় গ্রিডে কয়লার চেয়ে সৌরবিদ্যুতের অবদান বেশি ছিল। এতে নবায়নযোগ্য জ্বালানির দিকে দেশের অগ্রগতি স্পষ্ট হয়েছে।'),
  ('hilsa-season', 'b60415609c161aa4e82141631f72c080', 'As the monsoon rivers swell, the king of fish makes its annual journey upstream. Markets across the country are brimming with the prized hilsa.', 'বর্ষায় নদীর পানি বাড়ার সঙ্গে সঙ্গে উজানে বার্ষিক যাত্রা শুরু করেছে ইলিশ। দেশজুড়ে বাজারগুলো এখন এই জনপ্রিয় মাছে ভরে উঠেছে।'),
  ('jak-export', 'ea98e7668fa2788fc23753277d5f2011', 'Bangladesh''s readymade garment exports rose 11% in the last quarter, signalling a strong recovery. New orders from EU and US buyers are driving the growth.', 'গত প্রান্তিকে বাংলাদেশের তৈরি পোশাক রপ্তানি ১১ শতাংশ বেড়েছে, যা ঘুরে দাঁড়ানোর ইঙ্গিত দিচ্ছে। ইউরোপীয় ইউনিয়ন ও যুক্তরাষ্ট্রের ক্রেতাদের নতুন কার্যাদেশ এই প্রবৃদ্ধির চালিকাশক্তি।'),
  ('job-market-2025', 'c497d354ca3a748d0c7b0ee9b9087b20', 'Our analysis of hiring data reveals the ten skills that will dominate Bangladesh''s job market in 2025, from data literacy to Bangla AI prompting.', 'নিয়োগের তথ্য বিশ্লেষণ করে ২০২৫ সালে বাংলাদেশের চাকরির বাজারে চাহিদা থাকবে এমন দশটি দক্ষতা চিহ্নিত করেছি। তালিকায় আছে তথ্য বিশ্লেষণের প্রাথমিক জ্ঞান থেকে বাংলায় এআইকে নির্দেশনা দেওয়ার কৌশল।'),
  ('metro-extended-line', '70b60d985ebe48fc874bb0152b91a1a5', 'After weeks of anticipation, the Dhaka Metro Rail today completed its first test run on the extended line from Agargaon to Motijheel, marking a historic milestone for public transport in the capital.', 'কয়েক সপ্তাহের অপেক্ষার পর আগারগাঁও থেকে মতিঝিল পর্যন্ত বর্ধিত পথে আজ প্রথম পরীক্ষামূলক যাত্রা সম্পন্ন করেছে ঢাকা মেট্রোরেল। রাজধানীর গণপরিবহনে এটি এক ঐতিহাসিক মাইলফলক।'),
  ('monsoon-memories', '31bde61d9a2ccdfda79fbb498ccf3260', 'The monsoon is not just a weather event in Bangladesh — it is an economic system. From seed prices to boat-making, the rains choreograph rural livelihoods.', 'বাংলাদেশে বর্ষা আবহাওয়ার পাশাপাশি একটি অর্থনৈতিক ব্যবস্থাও। বীজের দাম থেকে নৌকা তৈরি পর্যন্ত গ্রামীণ জীবিকার ছন্দ নির্ধারণ করে বৃষ্টি।'),
  ('mosque-renovation', '55d643b6614e524ca292f91138333719', 'The iconic Star Mosque in Old Dhaka is undergoing careful restoration. Conservationists are working to preserve its unique mosaic work built in the early 19th century.', 'পুরান ঢাকার ঐতিহাসিক তারা মসজিদের সংস্কার চলছে। উনিশ শতকের গোড়ার দিকে তৈরি এর অনন্য মোজাইকের কাজ অক্ষুণ্ন রাখতে কাজ করছেন সংরক্ষণবিদরা।'),
  ('national-hackathon', '2f5738578371b67b296385db80eb4afd', 'Young developers from across the country are competing in a 48-hour hackathon to build AI solutions for agriculture, healthcare and disaster management in Bangladesh.', 'কৃষি, স্বাস্থ্যসেবা ও দুর্যোগ ব্যবস্থাপনায় এআই-ভিত্তিক সমাধান তৈরির জন্য দেশজুড়ে তরুণ ডেভেলপাররা ৪৮ ঘণ্টার হ্যাকাথনে অংশ নিচ্ছেন।'),
  ('national-park-trek', 'fb69418427d2640fd14d05cf24093929', 'Sajek Valley has opened two new trekking trails offering panoramic views of the hill tracts, complete with eco-lodges run by indigenous communities.', 'সাজেক উপত্যকায় দুটি নতুন হাঁটাপথ চালু হয়েছে। সেখান থেকে পার্বত্য এলাকার বিস্তৃত দৃশ্য দেখা যায় এবং স্থানীয় আদিবাসী সম্প্রদায়ের পরিচালিত পরিবেশবান্ধব আবাসনে থাকা যায়।'),
  ('padma-bridge-2', '83db7cd913452ffaebe500687c3358e2', 'Two years after its opening, the Padma Bridge has catalysed a manufacturing and logistics boom across the southwest, creating tens of thousands of jobs.', 'উদ্বোধনের দুই বছর পর পদ্মা সেতু দক্ষিণ-পশ্চিমাঞ্চলে শিল্প উৎপাদন ও পণ্য পরিবহনে গতি এনেছে। তৈরি হয়েছে কয়েক দশ হাজার কর্মসংস্থান।'),
  ('rail-new-route', '019460a9fbf0789fa710815cba7e497d', 'Bangladesh Railway has commissioned a feasibility study for a high-speed rail corridor between Dhaka and Chattogram, a project that could cut travel time to under 90 minutes.', 'ঢাকা ও চট্টগ্রামের মধ্যে উচ্চগতির রেলপথের সম্ভাব্যতা যাচাইয়ের উদ্যোগ নিয়েছে বাংলাদেশ রেলওয়ে। প্রকল্পটি বাস্তবায়িত হলে যাত্রার সময় ৯০ মিনিটের নিচে নেমে আসতে পারে।'),
  ('remittance-record', 'af83c8f6a4a3dff28dd0840e36b70b30', 'Bangladesh received record remittance inflows last month, crossing $2 billion for the first time. Experts credit formal banking channels and digital transfers for the surge.', 'গত মাসে বাংলাদেশে রেকর্ড পরিমাণ প্রবাসী আয় এসেছে, যা প্রথমবারের মতো ২০০ কোটি ডলার ছাড়িয়েছে। বিশেষজ্ঞরা এ বৃদ্ধির জন্য আনুষ্ঠানিক ব্যাংকিং চ্যানেল ও ডিজিটাল লেনদেনকে কৃতিত্ব দিয়েছেন।'),
  ('remote-work-trend', '6bac3bb02277be04b2751aaf13922b59', 'From rooftop cafés to co-working hubs, Dhaka''s workforce is embracing hybrid work. We explore the lifestyle shifts, challenges and opportunities of the new normal.', 'ছাদের ক্যাফে থেকে যৌথ কর্মস্থল পর্যন্ত ঢাকার কর্মীরা অফিস ও দূরবর্তী কাজ মিলিয়ে নতুন কর্মপদ্ধতি গ্রহণ করছেন। এই পরিবর্তনের জীবনযাত্রা, চ্যালেঞ্জ ও সুযোগ নিয়ে আমাদের প্রতিবেদন।'),
  ('rohingya-education', '942e257674beaaa6fa606eb325b5abf2', 'A UN delegation has praised Bangladesh''s efforts to provide education to Rohingya refugee children, calling the programme a regional model of compassion.', 'রোহিঙ্গা শরণার্থী শিশুদের শিক্ষার সুযোগ দিতে বাংলাদেশের প্রচেষ্টার প্রশংসা করেছে জাতিসংঘের একটি প্রতিনিধিদল। তারা কর্মসূচিটিকে এ অঞ্চলে মানবিকতার উদাহরণ বলে উল্লেখ করেছে।'),
  ('rte-act', '12eb678827f0b03743e007fabe525adb', 'Parliament is set to pass a landmark education act guaranteeing free and compulsory secondary education, alongside a charter of rights for teachers.', 'বিনা খরচে বাধ্যতামূলক মাধ্যমিক শিক্ষা নিশ্চিত করতে যুগান্তকারী একটি শিক্ষা আইন পাসের প্রস্তুতি নিচ্ছে সংসদ। এর সঙ্গে থাকছে শিক্ষকদের অধিকার সনদ।'),
  ('rural-internet', '4d6bc2c8d0c3b694c4cb78db62a3b4f6', 'Telecom operators have extended 4G coverage to 98% of the population, connecting remote villages and opening doors to digital services in education and healthcare.', 'মুঠোফোন অপারেটররা দেশের ৯৮ শতাংশ মানুষের কাছে ফোরজি নেটওয়ার্ক পৌঁছে দিয়েছে। দূরের গ্রামগুলো যুক্ত হওয়ায় শিক্ষা ও স্বাস্থ্যসেবায় ডিজিটাল সুবিধার সুযোগ তৈরি হচ্ছে।'),
  ('smart-tv-local', 'a3b87fd65f8c4b75090b71388cfaa68f', 'A new wave of local brands is challenging imported giants in the smart TV segment, offering competitive features with Bangla voice assistants and local content apps.', 'বাংলা ভয়েস অ্যাসিস্ট্যান্ট ও স্থানীয় কনটেন্টের অ্যাপসহ প্রতিযোগিতামূলক সুবিধা নিয়ে স্মার্ট টিভির বাজারে বড় আমদানি করা ব্র্যান্ডগুলোকে চ্যালেঞ্জ জানাচ্ছে দেশীয় ব্র্যান্ডগুলো।'),
  ('street-art-dhaka', '7c73777da6cd6ec65b660b9f57625a54', 'A vibrant street-art movement is transforming Dhaka''s grey walls into open-air galleries, giving voice to young creatives across the capital.', 'প্রাণবন্ত পথশিল্প ঢাকার ধূসর দেয়ালগুলোকে খোলা আকাশের নিচে প্রদর্শনীতে রূপ দিচ্ছে। রাজধানীর তরুণ সৃজনশীল মানুষেরা সেখানে নিজেদের কথা তুলে ধরছেন।'),
  ('street-food-guide', 'f1d3ce701fe6210e3dd142bafacd7031', 'From nihari at 4am to tangy fuchka at dusk, we take you on a mouth-watering tour of Old Dhaka''s legendary street food scene.', 'ভোর চারটার নেহারি থেকে গোধূলির টক ফুচকা—পুরান ঢাকার বিখ্যাত পথখাবারের স্বাদ নিতে ঘুরে দেখুন আমাদের সঙ্গে।'),
  ('sundarbans-crab', '799384749bb709fc048067d57ce028d0', 'On the banks of the Sundarbans, mud crab farming has become a lifeline for thousands of coastal families. We document a day in the life of these resilient entrepreneurs.', 'সুন্দরবনের পাড়ে হাজার হাজার উপকূলীয় পরিবারের জীবিকার ভরসা হয়ে উঠেছে কাঁকড়া চাষ। প্রতিকূলতা পেরিয়ে টিকে থাকা এসব উদ্যোক্তার এক দিনের গল্প তুলে ধরেছি।'),
  ('tigers-vs-afghanistan', 'db764b1c1c7c9a4c1d61dfc8fc1e0853', 'Bangladesh take on Afghanistan in a must-win World Cup qualifier tonight. A victory would put the Tigers on the brink of a historic World Cup appearance.', 'বিশ্বকাপ বাছাইয়ের গুরুত্বপূর্ণ ম্যাচে আজ রাতে আফগানিস্তানের মুখোমুখি বাংলাদেশ। জয় পেলে ঐতিহাসিক বিশ্বকাপ অংশগ্রহণের আরও কাছাকাছি যাবে টাইগাররা।'),
  ('tortured-women', '6b4ec2ad162ef68f561171620714f44a', 'Behind every export milestone stand millions of women whose quiet courage powers the nation''s economy. Their story deserves more than statistics.', 'রপ্তানির প্রতিটি মাইলফলকের পেছনে আছেন লাখো নারী, যাঁদের নীরব সাহস দেশের অর্থনীতিকে এগিয়ে নেয়। শুধু পরিসংখ্যান দিয়ে তাঁদের গল্প বলা যায় না।'),
  ('un-cop-climate', 'ff37b382fe96bfd6096ad327045adb28', 'Bangladesh has again urged developed nations to deliver on their $100 billion climate finance pledge, warning that vulnerable deltas cannot wait for another summit cycle.', 'উন্নত দেশগুলোকে ১০ হাজার কোটি ডলারের জলবায়ু অর্থায়নের প্রতিশ্রুতি পূরণের আহ্বান জানিয়েছে বাংলাদেশ। ঝুঁকিপূর্ণ বদ্বীপগুলো আরেকটি সম্মেলন পর্যন্ত অপেক্ষা করতে পারে না বলে সতর্ক করেছে দেশটি।'),
  ('vaccine-drive', '6a1570f04446a9efd21e44bd60d5f389', 'Health authorities have launched an ambitious vaccination drive aimed at reaching 30 million people in 90 days, focusing on rural areas with limited access to care.', '৯০ দিনে তিন কোটি মানুষকে টিকা দেওয়ার লক্ষ্য নিয়ে স্বাস্থ্য কর্তৃপক্ষ কর্মসূচি শুরু করেছে। স্বাস্থ্যসেবার সুযোগ কম, এমন গ্রামগুলোকে অগ্রাধিকার দেওয়া হচ্ছে।'),
  ('women-coders', '527f75464ddfce319046b89f2197ab6c', 'From rural bootcamps to boardrooms, Bangladeshi women are reshaping the tech landscape. Meet five engineers who are changing the face of the country''s IT industry.', 'গ্রামের প্রশিক্ষণশিবির থেকে করপোরেট বোর্ডরুম পর্যন্ত প্রযুক্তি অঙ্গন বদলে দিচ্ছেন বাংলাদেশের নারীরা। দেশের আইটি শিল্পকে নতুন রূপ দেওয়া পাঁচ প্রকৌশলীর সঙ্গে পরিচিত হোন।')
) t(slug,digest,original_excerpt,summary_bn)
where a.slug=t.slug and md5(a.body)=t.digest and a.excerpt=t.original_excerpt;

insert into public.article_editions(article_id,source_digest,excerpt_en,body_en)
select a.id,md5(a.body || chr(31) || a.excerpt || chr(31) || a.title_bn),t.summary_en,t.body_en
from public.articles a cross join (values
  ('bangladesh-tightens-power-saving-measures-as-gas-shortages-worsen', '764f02d5978a95631b224a4c4a282355', 'তীব্র গ্যাস সংকট ও দীর্ঘ সময়ের বিদ্যুৎ বিভ্রাটের মধ্যে বাংলাদেশে বিদ্যুৎ সাশ্রয়ের পদক্ষেপ আরও কঠোর করা হয়েছে। নতুন নির্দেশনায় দোকান, মার্কেট ও শপিংমল রাত ৮টার মধ্যে বন্ধ করতে বলা হয়েছে।', 'Bangladesh has tightened electricity-saving measures amid severe gas shortages and prolonged outages. Under the new directive, shops, markets and shopping malls must close by 8 p.m.', 'Worsening gas shortages in Bangladesh have put electricity generation under pressure. With prolonged outages in several parts of the country, the government has tightened restrictions on electricity use and shortened business hours.

Under a directive effective August 13, shopping malls, markets and retailers may operate from 11 a.m. to 8 p.m. Hospitals, pharmacies and food businesses are exempt.

Reduced gas supplies have disrupted power generation. The report says the national grid faces a shortfall of several hundred megawatts during peak hours. Load shedding has increased, with some areas experiencing extended outages.

Bangladesh is increasingly reliant on imported LNG to meet demand, making its energy system sensitive to changes in international supply and prices. Recent problems at LNG terminals have added pressure. The Middle East crisis has also increased uncertainty over LNG prices and availability, making it harder for import-dependent countries such as Bangladesh to maintain power generation and control energy costs.

The government hopes its new measures will ease demand. If gas supplies do not return to normal soon, there are fears that the impact on electricity generation, industry and commerce will grow.'),
  ('devastating-earthquake-hits-colombia-death-toll-rises-to-265', '001504209ddd40595f922aa8f5826189', 'কলম্বিয়ায় ৭.৪ মাত্রার শক্তিশালী ভূমিকম্পে মৃতের সংখ্যা বেড়ে ২৬৫ জনে পৌঁছেছে। প্রায় ৫০০ মানুষ এখনো নিখোঁজ রয়েছেন। ধ্বংসস্তূপে জীবিতদের খুঁজতে উদ্ধারকারীদের অভিযান গুরুত্বপূর্ণ পর্যায়ে পৌঁছেছে।', 'The death toll from a magnitude 7.4 earthquake in Colombia has risen to 265, with nearly 500 people still missing. The search for survivors in the rubble has reached a critical stage.', 'A magnitude 7.4 earthquake in western Colombia has caused a humanitarian disaster. At least **265 people have been confirmed dead** since the August 10 quake, and nearly 500 are still missing. Thousands have been injured and many families have lost their homes.

The epicentre was near San José del Palmar in the department of Chocó. Buildings and vital infrastructure in Cali, Pereira, Manizales and surrounding areas suffered extensive damage. Some schools, hospitals and residential buildings were damaged or collapsed.

Rescue teams have been clearing rubble and searching for survivors around the clock, intensifying operations in Cali and Pereira. Officials say the chances of finding survivors are declining as the critical 72-hour rescue window has passed.

More than 150 aftershocks have been recorded. Crews working near collapsed buildings must proceed with extreme caution because of the risk of further collapses.

Colombia’s new president, Abelardo de la Espriella, announced an emergency fund to rebuild the affected regions. The government is accepting international assistance and preparing to rebuild hospitals, schools, homes and other infrastructure.

Rescue operations continue. Teams are searching every possible location for people trapped under debris. Families of the missing are still waiting in hope that their relatives may be alive beneath the rubble.'),
  ('global-markets-focus-on-iran-as-oil-prices-stay-below-90', 'c90ad0e29660413b859531bbf68be704', 'ইরানকে ঘিরে চলমান ভূরাজনৈতিক অনিশ্চয়তার মধ্যেও বৈশ্বিক শেয়ারবাজারে সামান্য ঊর্ধ্বগতি দেখা গেছে। তেলের দাম ব্যারেলপ্রতি ৯০ ডলারের নিচে থাকলেও হরমুজ প্রণালী ও মধ্যপ্রাচ্যের পরিস্থিতি নিয়ে বিনিয়োগকারীদের উদ্বেগ অব্যাহত রয়েছে।', 'Global stocks edged higher despite geopolitical uncertainty surrounding Iran. Oil remained below $90 a barrel, but investors remained concerned about the Strait of Hormuz and the wider Middle East.', 'Global equities edged higher on Thursday amid tensions in the Middle East and uncertainty over Iran. Investors continued to watch developments in Iran, energy supplies and prospects for the Strait of Hormuz.

International oil prices eased below $90 a barrel. According to Reuters, Brent crude fell to about $88 on Thursday. A large rise in US crude inventories and fears of weakening global energy demand weighed on prices.

Supply risks remain despite lower prices. US-Iran talks over the Strait of Hormuz remain unresolved, and shipping through the waterway has fallen to a three-week low. A sudden change in conditions could bring renewed volatility to oil markets.

Shares in technology and AI infrastructure companies performed relatively well. Strong earnings reports and continued investment in AI have kept technology among the main drivers of equity markets.

Analysts say developments in Iran, oil supplies and US economic data could play an important role in shaping global markets in the coming days.'),
  ('nvidia-partners-with-wall-street-giants-to-raise-500-billion-for-ai-infrastructure', '238af0179df13355f4b69c1447604d06', 'কৃত্রিম বুদ্ধিমত্তার অবকাঠামো সম্প্রসারণে নতুন বড় উদ্যোগ নিয়েছে Nvidia। ছয়টি বড় আর্থিক প্রতিষ্ঠানের সঙ্গে অংশীদারত্বের মাধ্যমে AI অবকাঠামো খাতে ৫০০ বিলিয়ন ডলারের বেশি তৃতীয় পক্ষের মূলধন সংগ্রহের পরিকল্পনা করেছে প্রতিষ্ঠানটি।', 'Nvidia has launched a financing initiative for AI infrastructure. Through partnerships with six major financial institutions, the company aims to raise more than $500 billion in third-party capital.', 'As artificial intelligence expands, global demand for AI data centres and computing infrastructure is growing. Chipmaker Nvidia has launched an initiative to secure financing on a large scale.

According to Reuters, Nvidia is partnering with six major financial institutions to launch compute financing platforms. The aim is to raise more than $500 billion in third-party capital to build and expand AI infrastructure.

Training and running AI models requires large numbers of GPUs and servers, as well as data centres and power infrastructure. Banks and investment firms are joining technology companies in seeking major investment opportunities in the sector.

If successful, Nvidia’s initiative could accelerate the expansion of AI computing capacity and open up financing for new data centres. It could also strengthen the position of the US technology sector in global AI competition.

The analysis suggests that the next phase of AI competition will extend beyond developing new models. The ability to build the largest and most powerful computing infrastructure is becoming an important part of that contest.'),
  ('us-iran-talks-stall-over-strait-of-hormuz-oil-prices-rise-amid-growing-uncertainty', 'b6c8a7170d313e887214490cb2bb5271', 'হরমুজ প্রণালী পুনরায় চালু করা ও শান্তিচুক্তি নিয়ে যুক্তরাষ্ট্র ও ইরানের আলোচনায় অচলাবস্থা তৈরি হয়েছে। এর প্রভাব পড়েছে আন্তর্জাতিক তেলের বাজারে।', 'US-Iran talks on a peace agreement and reopening the Strait of Hormuz have stalled, affecting international oil markets.', 'Fresh uncertainty has emerged in talks between the United States and Iran over a peace agreement and the safe reopening of the Strait of Hormuz. Differences between the two sides have raised concerns about the prospects for a quick agreement.

The strait is one of the world’s most important energy transport routes. Large volumes of oil and gas pass through it on their way to international markets. Uncertainty about security and normal shipping can therefore cause rapid swings in global oil prices.

International oil prices rose on Tuesday, August 11. According to Reuters, Brent crude reached about $88 per barrel and US crude about $82.45. Investors were watching the progress of US-Iran talks and developments in the strait.

Analysts fear that a longer stalemate could intensify concerns over energy supplies. The effects could extend beyond oil markets to transport costs, inflation and the global economy. Governments and market observers around the world are monitoring the situation closely.')
) t(slug,digest,original_excerpt,summary_en,body_en)
